int effectiveLimit = Math.max(1, (limit ?: 100) as Integer) def dd = ec.entity.find('moqui.entity.document.DataDocument') .condition('dataDocumentId', dataDocumentId) .one() if (!dd) { documentList = [] documentCount = 0 rawRowList = [] rawRowCount = 0 return }
