, int maxLength -> String text = (rawValue ?: '').toString() if (!text || text.length() <= maxLength) return text String hash = MessageDigest.getInstance('SHA-1').digest(text.getBytes('UTF-8')).encodeHex().toString() String suffix = '-' + hash.substring(0, Math.min(12, hash.length())) int prefixLength = Math.max(0, maxLength - suffix.length()) return text.substring(0, prefixLength) + suffix } Map<String, String> vertexParameterDefByKey = [ graphVertexType : 'AgGraphVertexTypeParam', sourceVertexId : 'AgGraphSourceVertexIdParam', sourceArtifactUri : 'AgGraphSourceArtifactUriParam', artifactKind : 'AgGraphArtifactKindParam', screenPath : 'AgGraphScreenPathParam', serviceName : 'AgGraphServiceNameParam', serviceVerb : 'AgGraphServiceVerbParam', serviceNoun : 'AgGraphServiceNounParam', entityName : 'AgGraphEntityNameParam', fieldName : 'AgGraphFieldNameParam', documentType : 'AgGraphDocumentTypeParam', xmlActionElement : 'AgGraphXmlActionElementParam', statementClass : 'AgGraphStatementClassParam', grammarAttributes : 'AgGraphGrammarAttributesParam', grammarChildren : 'AgGraphGrammarChildrenParam', grammarSubstitutionGroup : 'AgGraphGrammarSubstitutionGroupParam', domainObject : 'AgGraphDomainObjectParam', subject : 'AgGraphSubjectParam', operation : 'AgGraphOperationParam', calledService : 'AgGraphCalledServiceParam', parameterRole : 'AgGraphParameterRoleParam', securityArtifactName : 'AgGraphSecurityArtifactNameParam', securityArtifactTypeEnumId : 'AgGraphSecurityArtifactTypeParam', artifactGroupId : 'AgGraphArtifactGroupIdParam', artifactGroupDescription : 'AgGraphArtifactGroupDescriptionParam', artifactAuthzId : 'AgGraphArtifactAuthzIdParam', userGroupId : 'AgGraphUserGroupIdParam', authzTypeEnumId : 'AgGraphAuthzTypeEnumIdParam', authzActionEnumId : 'AgGraphAuthzActionEnumIdParam', authzServiceName : 'AgGraphAuthzServiceNameParam', entityFilterSetId : 'AgGraphEntityFilterSetIdParam', entityFilterId : 'AgGraphEntityFilterIdParam', comparisonEnumId : 'AgGraphComparisonEnumIdParam', applyCond : 'AgGraphApplyCondParam', nameIsPattern : 'AgGraphNameIsPatternParam', inheritAuthz : 'AgGraphInheritAuthzParam', filterMap : 'AgGraphFilterMapParam', allowMissingAlias : 'AgGraphAllowMissingAliasParam', joinOr : 'AgGraphJoinOrParam', maxHitsCount : 'AgGraphMaxHitsCountParam', maxHitsDuration : 'AgGraphMaxHitsDurationParam', tarpitDuration : 'AgGraphTarpitDurationParam' ] Map<String, String> edgeParameterDefByKey = [ sourceEdgeId : 'AgGraphSourceEdgeIdParam', edgeRelation : 'AgGraphEdgeRelationParam', serviceName : 'AgGraphServiceNameParam', entityName : 'AgGraphEntityNameParam', fieldName : 'AgGraphFieldNameParam', edgeRole : 'AgGraphEdgeRoleParam' ] Closure<String> normalizeVertexType = { Object rawType -> String text = (rawType ?: '').toString().trim() if (!text) return 'Unknown' switch (text) { case 'ScreenTransition': return 'Transition' case 'ServiceActionStatement': return 'XmlAction' default: return text } } Closure<String> makeParameterId = { String parameterDefId, String graphVertexId, String graphEdgeId -> String source = "${effectiveGraphId}|${graphVertexId ?: ''}|${graphEdgeId ?: ''}|${parameterDefId}" return MessageDigest.getInstance('SHA-1').digest(source.getBytes('UTF-8')).encodeHex().toString() } Set<String> emittedParameterIds = new LinkedHashSet<String>() Closure<Void> storeGraphParameter = { String parameterDefId, Object rawValue, String graphVertexId, String graphEdgeId, int sequenceNum -> String textValue = (rawValue ?: '').toString() if (!textValue) return String symbolicValue = normalizeSizedText(textValue, 63) String parameterId = makeParameterId(parameterDefId, graphVertexId, graphEdgeId) if (emittedParameterIds.contains(parameterId)) return emittedParameterIds.add(parameterId) boolean alwaysCreate = Boolean.TRUE.equals(clearExisting) def parameterValue = null boolean newParameter = true if (!alwaysCreate) { parameterValue = ec.entity.find('moqui.math.Parameter').condition('parameterId', parameterId).one() newParameter = parameterValue == null if (parameterValue) parameterValue = parameterValue.cloneValue() } if (!parameterValue) { parameterValue = ec.entity.makeValue('moqui.math.Parameter') parameterValue.parameterId = parameterId } parameterValue.parameterDefId = parameterDefId parameterValue.mathModelId = effectiveMathModelId parameterValue.graphId = effectiveGraphId parameterValue.graphVertexId = graphVertexId parameterValue.graphEdgeId = graphEdgeId parameterValue.sequenceNum = sequenceNum parameterValue.symbolicValue = symbolicValue parameterValue.textValue = textValue if (newParameter) parameterValue.create() else parameterValue.update() }
