ertex.inheritAuthz ?: ''), filterMap : (vertex.filterMap ?: ''), allowMissingAlias : (vertex.allowMissingAlias ?: ''), joinOr : (vertex.joinOr ?: ''), maxHitsCount : (vertex.maxHitsCount ?: ''), maxHitsDuration : (vertex.maxHitsDuration ?: ''), tarpitDuration : (vertex.tarpitDuration ?: '') ] int vertexParameterSeq = 1 vertexParameters.each { String metadataKey, Object metadataValue -> String parameterDefId = vertexParameterDefByKey[metadataKey] if (parameterDefId) { storeGraphParameter(parameterDefId, metadataValue, graphVertexId, null, vertexParameterSeq) vertexParameterSeq++ } } loadedVertexCount++ }
edgesFile.eachLine('UTF-8') { String line -> String trimmed = line?.trim() if (!trimmed) return Map edge = slurper.parseText(trimmed) as Map String rawGraphEdgeId = (edge.edgeId ?: '').toString() String rawFromVertexId = (edge.fromVertexId ?: '').toString() String rawToVertexId = (edge.toVertexId ?: '').toString() if (!rawGraphEdgeId || !rawFromVertexId || !rawToVertexId) return String graphEdgeId = normalizeEdgeId(rawGraphEdgeId) String fromVertexId = normalizeVertexId(rawFromVertexId) String toVertexId = normalizeVertexId(rawToVertexId)
