Closure<String> sha1 = { String text -> MessageDigest.getInstance('SHA-1').digest((text ?: '').getBytes('UTF-8')).encodeHex().toString() } Closure<String> normalizeToken = { Object rawValue -> String text = (rawValue ?: '').toString().trim() if (!text) return '' text = text.replaceAll(/([a-z0-9])([A-Z])/, '$1 $2') text = text.replaceAll(/[^A-Za-z0-9]+/, ' ') List<String> parts = text.tokenize(' ') if (!parts) return '' String normalized = parts.collect { String part -> if (!part) return '' part.substring(0, 1).toUpperCase() + (part.length() > 1 ? part.substring(1) : '') }.join('') if (normalized && Character.isDigit(normalized.charAt(0))) normalized = 'N' + normalized return normalized } Closure<String> compactGraphId = { String graphRole, String domainNameValue, String subdomainNameValue -> String rolePrefix = graphRole == 'subdomain' ? 'AgSub' : 'AgDom' String domainToken = normalizeToken.call(domainNameValue) if (domainToken.length() > 10) domainToken = domainToken.substring(0, 10) String subdomainToken = normalizeToken.call(subdomainNameValue) if (subdomainToken.length() > 8) subdomainToken = subdomainToken.substring(0, 8) String hashSource = [sourceGraphId, graphRole, domainNameValue ?: '', subdomainNameValue ?: ''].join('|') String hashSuffix = sha1(hashSource).substring(0, 12) String compactId = [rolePrefix, domainToken, subdomainToken, hashSuffix].findAll { it }.join('_') if (compactId.length() > 40) compactId = "${rolePrefix}_${hashSuffix}" return compactId } Closure<String> simpleName = { Object rawValue -> String text = (rawValue ?: '').toString().trim() if (!text) return '' if (text.contains('#')) text = text.substring(text.lastIndexOf('#') + 1) if (text.contains('.')) text = text.tokenize('.').last() return text } Closure<String> fitShortText = { Object rawValue, int maxLength -> String text = (rawValue ?: '').toString() if (!text) return '' return text.length() > maxLength ? text.substring(0, maxLength) : text } Closure<String> extractComponentName = { String sourceArtifactUri -> String uri = (sourceArtifactUri ?: '').toString() if (!uri) return '' if (uri.startsWith('component://')) return uri.substring('component://'.length()).tokenize('/')[0] int runtimeIdx = uri.indexOf('/runtime/component/') if (runtimeIdx >= 0) { String rest = uri.substring(runtimeIdx + '/runtime/component/'.length()) return rest.tokenize('/')[0] } if (uri.contains('/framework/')) return 'framework' return '' } Closure<String> extractPackageName = { Map row -> String entityNameValue = (row.entityName ?: '').toString() if (entityNameValue.contains('.')) return entityNameValue.substring(0, entityNameValue.lastIndexOf('.')) String serviceNameValue = (row.serviceName ?: '').toString() if (serviceNameValue) { String beforeHash = serviceNameValue.contains('#') ? serviceNameValue.substring(0, serviceNameValue.indexOf('#')) : serviceNameValue String afterHash = serviceNameValue.contains('#') ? serviceNameValue.substring(serviceNameValue.indexOf('#') + 1) : '' if (beforeHash.contains('.')) return beforeHash.substring(0, beforeHash.lastIndexOf('.')) if (afterHash.contains('.')) return afterHash.substring(0, afterHash.lastIndexOf('.')) } String sourceArtifactUri = (row.sourceArtifactUri ?: '').toString() if (sourceArtifactUri.contains('/service/')) { String rest = sourceArtifactUri.substring(sourceArtifactUri.indexOf('/service/') + '/service/'.length()) List<String> parts = rest.tokenize('/') if (parts.size() > 1) return parts[0..-2].join('.') } if (sourceArtifactUri.contains('/entity/')) { String rest = sourceArtifactUri.substring(sourceArtifactUri.indexOf('/entity/') + '/entity/'.length()) List<String> parts = rest.tokenize('/') if (parts.size() > 1) return parts[0..-2].join('.') } String componentNameValue = extractComponentName(sourceArtifactUri) return componentNameValue ? "component.${componentNameValue}" : '' } Closure<String> extractScreenArea = { Map row -> String screenPathValue = (row.screenPath ?: '').toString() if (screenPathValue) { List<String> seg = screenPathValue.tokenize('/') if (seg && seg[0] == 'SimpleScreens' && seg.size() > 1) return seg[1] if (seg) return seg[0] } String sourceArtifactUri = (row.sourceArtifactUri ?: '').toString() def matcher = sourceArtifactUri =~ /\/screen\/(?:SimpleScreens\/)?([^\/]+)\/([^\/]+)\/[^\/]+\.xml$/ if (matcher.find()) return matcher.group(1) return '' } Closure<String> extractScreenSubArea = { Map row -> String screenPathValue = (row.screenPath ?: '').toString() if (screenPathValue) { List<String> seg = screenPathValue.tokenize('/') if (seg && seg[0] == 'SimpleScreens' && seg.size() > 2) return seg[2] if (seg.size() > 1) return seg[1] } String sourceArtifactUri = (row.sourceArtifactUri ?: '').toString() def matcher = sourceArtifactUri =~ /\/screen\/(?:SimpleScreens\/)?([^\/]+)\/([^\/]+)\/[^\/]+\.xml$/ if (matcher.find()) return matcher.group(2) return '' } Closure<String> mapPackageToDomain = { String packageNameValue -> String pkg = (packageNameValue ?: '').toLowerCase() if (!pkg) return '' if (pkg.contains('mantle.order')) return 'Order' if (pkg.contains('mantle.party')) return 'Party' if (pkg.contains('mantle.product')) return 'Product' if (pkg.contains('mantle.work')) return 'WorkEffort' if (pkg.contains('mantle.request')) return 'Request' if (pkg.contains('mantle.shipment')) return 'Shipment' if (pkg.contains('mantle.facility')) return 'Facility' if (pkg.contains('mantle.content')) return 'Content' if (pkg.contains('mantle.account') || pkg.contains('mantle.ledger')) return 'Accounting' if (pkg.contains('mantle.other.budget')) return 'Budget' if (pkg.contains('mantle.other')) return 'Other' if (pkg.contains('org.moqui.agent') || pkg.contains('moqui.agent')) return 'Agent' if (pkg.contains('moqui.security')) return 'Security' if (pkg.contains('moqui.entity')) return 'Entity' if (pkg.contains('moqui.service')) return 'Service' return '' } Closure<String> normalizeFileStem = { String sourceArtifactUri -> String uri = (sourceArtifactUri ?: '').toString() if (!uri) return '' String name = uri.tokenize('/').last() if (name.endsWith('.xml')) name = name.substring(0, name.length() - 4) name = name.replaceAll(/(Services|Entities|Screens|Screen|Forms|Transitions)$/, '') normalizeToken(name) } Closure<String> deriveDomainName = { Map row -> String screenArea = normalizeToken(extractScreenArea(row)) if (screenArea) return screenArea String mappedPackageDomain = normalizeToken(mapPackageToDomain(extractPackageName(row))) if (mappedPackageDomain) return mappedPackageDomain String domainObjectValue = normalizeToken(row.domainObject) if (domainObjectValue) return domainObjectValue String entitySimple = normalizeToken(simpleName(row.entityName)) if (entitySimple) return entitySimple String serviceNounValue = normalizeToken(row.serviceNoun) if (serviceNounValue) return serviceNounValue String fileStem = normalizeFileStem((row.sourceArtifactUri ?: '').toString()) if (fileStem) return fileStem String componentNameValue = normalizeToken(extractComponentName((row.sourceArtifactUri ?: '').toString())) if (componentNameValue) return componentNameValue return 'Unclassified' } Closure<String> deriveSubdomainName = { Map row, String domainNameValue -> String screenSubArea = normalizeToken(extractScreenSubArea(row)) if (screenSubArea && screenSubArea != domainNameValue) return screenSubArea String domainObjectValue = normalizeToken(row.domainObject) if (domainObjectValue && domainObjectValue != domainNameValue) return domainObjectValue String serviceNounValue = normalizeToken(row.serviceNoun) if (serviceNounValue && serviceNounValue != domainNameValue) return serviceNounValue String entitySimple = normalizeToken(simpleName(row.entityName)) if (entitySimple && entitySimple != domainNameValue) return entitySimple String fileStem = normalizeFileStem((row.sourceArtifactUri ?: '').toString()) if (fileStem && fileStem != domainNameValue) return fileStem return '' }
