Closure<String> makeParameterId = { String effectiveGraphId, String parameterDefId, String graphVertexId, String graphEdgeId -> sha1("${effectiveGraphId}|${graphVertexId ?: ''}|${graphEdgeId ?: ''}|${parameterDefId}") } Closure<Void> storeParameter = { String effectiveGraphId, String parameterDefId, Object rawValue, String graphVertexId, String graphEdgeId, int sequenceNum -> String textValue = (rawValue ?: '').toString() if (!textValue) return String parameterId = makeParameterId(effectiveGraphId, parameterDefId, graphVertexId, graphEdgeId) def parameterValue = ec.entity.find('moqui.math.Parameter').condition('parameterId', parameterId).one() boolean newParameter = parameterValue == null if (parameterValue) parameterValue = parameterValue.cloneValue() if (!parameterValue) { parameterValue = ec.entity.makeValue('moqui.math.Parameter') parameterValue.parameterId = parameterId } parameterValue.graphId = effectiveGraphId parameterValue.graphVertexId = graphVertexId parameterValue.graphEdgeId = graphEdgeId parameterValue.parameterDefId = parameterDefId parameterValue.sequenceNum = sequenceNum parameterValue.symbolicValue = textValue.length() <= 63 ? textValue : textValue.substring(0, 63) parameterValue.textValue = textValue if (newParameter) parameterValue.create() else parameterValue.update() } Closure<Void> ensureGraph = { String targetGraphId, String parentGraphId, String graphNameValue, String graphDescriptionValue, Map graphTopology -> def graphValue = ec.entity.find('moqui.math.Graph').condition('graphId', targetGraphId).one() boolean newGraph = graphValue == null if (graphValue) graphValue = graphValue.cloneValue() if (!graphValue) { graphValue = ec.entity.makeValue('moqui.math.Graph') graphValue.graphId = targetGraphId } graphValue.parentGraphId = parentGraphId graphValue.graphTypeEnumId = derivedGraphTypeEnumId graphValue.name = normalizeSizedText(graphNameValue, 63) graphValue.description = graphDescriptionValue graphValue.loopsAllowed = 'N' graphValue.isWeigh